BEGIN READ ONLY;
SET LOCAL statement_timeout = '7s';
SELECT jsonb_build_object('snapshot_utc',current_timestamp,'read_only',current_setting('transaction_read_only'),'database',current_database(),'tables', (SELECT jsonb_agg(to_jsonb(v)) FROM (SELECT t.tablename,t.isactive,t.ad_table_id,COALESCE((SELECT jsonb_agg(DISTINCT w.name) FROM adempiere.ad_tab b JOIN adempiere.ad_window w ON w.ad_window_id=b.ad_window_id WHERE b.ad_table_id=t.ad_table_id AND b.isactive='Y' AND w.isactive='Y'),'[]'::jsonb) AS native_windows FROM adempiere.ad_table t WHERE LOWER(t.tablename) IN ('m_product','pp_product_bom','pp_product_bomline','c_order','c_orderline','c_tax','m_pricelist','m_productprice','m_discountschema','c_uom_conversion','c_opportunity','c_commission','c_commissionrun','c_commissionamt','c_commissiondetail','c_campaign','m_storagereservation','eva_canalvanzare','eva_comandasite','eva_comandasitelinie','eva_mapareprodussite') ORDER BY t.tablename) v),'forms',(SELECT jsonb_agg(to_jsonb(v)) FROM (SELECT name,classname,isactive FROM adempiere.ad_form WHERE LOWER(classname) LIKE ANY(ARRAY['%wevacanalb2bform','%wevavanzaripecanalform','%wevawebcatalogform'])) v),'processes',(SELECT jsonb_agg(to_jsonb(v)) FROM (SELECT name,classname,isactive FROM adempiere.ad_process WHERE LOWER(classname) LIKE ANY(ARRAY['%commissioncalc','%fisacanalproces','%valideazacomenzi'])) v));
ROLLBACK;
